-- 실제로 만들어진 것

@RestController
class WhoController {
    private final OrderService service;
    WhoController(OrderService service) { this.service = service; }

    @GetMapping(value = "/who", produces = "text/plain")
    String who() {
        return "주입된 것: " + service.getClass().getName() + "\n"
             + "원본:      " + AopProxyUtils.ultimateTargetClass(service).getName() + "\n"
             + "프록시인가: " + AopUtils.isAopProxy(service) + "\n";
    }
}

$ curl -s localhost:8080/who
주입된 것: study.adv.OrderService
원본:      study.adv.OrderService
프록시인가: false

--   아직은 같다
--   이 책은 이 셋이 갈라지는 이야기다


-- 한 줄을 더한다

@Aspect
@Component
class TimeAspect {
    @Around("execution(* study.adv..*Service.*(..))")
    public Object around(ProceedingJoinPoint pjp) throws Throwable {
        long t0 = System.nanoTime();
        try {
            return pjp.proceed();
        } finally {
            System.out.printf("[측정] %s %.2f ms%n",
                pjp.getSignature().getName(), (System.nanoTime() - t0) / 1e6);
        }
    }
}

